// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public {
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(address actor, bytes32 role) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));

        // deployer (test contract) holds TIMELOCK_ADMIN_ROLE and grants it to actor
        c.grantRole(c.TIMELOCK_ADMIN_ROLE(), actor);
        assertTrue(c.hasRole(c.TIMELOCK_ADMIN_ROLE(), actor));

        // actor renounces the admin role for itself (must be for self)
        vm.startPrank(actor);
        c.renounceRole(c.TIMELOCK_ADMIN_ROLE(), actor);

        // after renouncing, actor must no longer be able to grant any role
        bool ok;
        try c.grantRole(role, actor) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        assertTrue(!ok && !c.hasRole(c.TIMELOCK_ADMIN_ROLE(), actor));
    }
}
